{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Fevipiprant absolute bioavailability was estimated as 30-40% in humans using an intravenous microdose comparator, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Vixotrigine is reported to have high oral bioavailability in humans, supporting a high F prediction for the query despite modest structural similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pritelivir showed 75% oral bioavailability in a human ascending-dose trial, providing strong supportive evidence that heteroaromatic oral drugs with polar groups can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Rufinamide, a fluorobenzyl-substituted azole heterocycle, has 85% oral bioavailability in patients, supporting high F for the similarly substituted query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Alfuzosin absolute bioavailability was 64.5% in healthy subjects, supporting high oral bioavailability for a nitrogen-rich heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "R406, a pyrimidine-containing kinase inhibitor, had absolute oral bioavailability of 54.6% in humans, supporting high F for the query's pyrimidine-based scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Encainide absolute oral bioavailability was 20-30% in healthy subjects, meeting the F >= 20% threshold and supporting a high prediction even for compounds with substantial first-pass metabolism.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental analogues, despite low Morgan similarity, report absolute oral bioavailability values at or above 20% (mostly 23-85%), and none provide affirmative evidence for F < 20%. The query's moderately polar heteroaromatic structure is consistent with these absorbable oral drugs, so high (F >= 20%) is predicted.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "All evidence molecules have low Morgan similarity (<0.25), limiting structural transferability.",
    "No human PK or metabolic stability data for the query to assess first-pass effects."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

